from django.utils.text import slugify


def populate_project_and_service_slugs(apps, schema_editor):
    Project = apps.get_model("core", "Project")
    Service = apps.get_model("core", "Service")

    service_slugs = {
        "e-commerce development": "ecommerce",
        "corporate web solutions": "corporate-web",
        "corporate web solution": "corporate-web",
        "custom software apps": "custom-software",
        "custom software app": "custom-software",
        "ui / ux design & frontend": "ui-ux",
    }
    for model, fallback in ((Project, "project"), (Service, "service")):
        used = set(model.objects.exclude(slug__isnull=True).values_list("slug", flat=True))
        for item in model.objects.filter(slug__isnull=True).order_by("pk"):
            base = (
                service_slugs.get(item.title.casefold(), slugify(item.title))
                if model is Service
                else slugify(item.title)
            )
            base = base[:210].strip("-") or f"{fallback}-{item.pk}"
            candidate = base
            suffix = 2
            while candidate in used:
                candidate = f"{base[:210 - len(str(suffix)) - 1]}-{suffix}"
                suffix += 1
            item.slug = candidate
            item.save(update_fields=["slug"])
            model.objects.filter(pk=item.pk).update(is_published=True)
            used.add(candidate)


def clear_project_and_service_slugs(apps, schema_editor):
    for model_name in ("Project", "Service"):
        apps.get_model("core", model_name).objects.update(slug=None, is_published=False)


